import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const before = execFileSync('git', ['show', 'HEAD:src/report_queries.js'], { encoding: 'utf8' });
const after = readFileSync('src/report_queries.js', 'utf8');
let events;
let failure;
const rows = [{ item: 'coffee', cents: 1200 }];
globalThis.__reportOpenDatabase = (path, { readOnly = false } = {}) => {
  events.push(['open', path, readOnly]);
  if (failure === 'open') throw new Error('open failed');
  return {
    prepare(sql) {
      events.push(['prepare', sql]);
      if (failure === 'prepare') throw new Error('prepare failed');
      return Object.fromEntries(['all', 'run'].map(method => [method, (...args) => {
        events.push([method, ...args]);
        if (failure === 'execute') throw new Error('execute failed');
        return method === 'all' ? rows : { changes: 1 };
      }]));
    },
    close() {
      events.push(['close']);
      if (failure === 'close') throw new Error('close failed');
    }
  };
};
const load = source => import('data:text/javascript;base64,' + Buffer.from(source.replace(
  \"import { openDatabase } from './db.js';\",
  'const openDatabase = globalThis.__reportOpenDatabase;'
)).toString('base64'));
const original = await load(before);
const refactored = await load(after);
assert.deepEqual(Object.keys(refactored), Object.keys(original));
const calls = [
  ['dailyTotals', ['shop-1', '2026-10-23']],
  ['topItems', ['shop-1', '2026-10-23']],
  ['topItems', ['shop-1', '2026-10-23', 2]],
  ['weeklyTotals', ['shop-1', '2026-10-19']],
  ['markReportSent', [42, '2026-10-23T07:00:00Z']]
];
function capture(module, name, args) {
  events = [];
  try { return { value: module[name](...args), events }; }
  catch (error) { return { error: error.message, events }; }
}
let checked = 0;
for (const [name, args] of calls) {
  assert.equal(refactored[name].length, original[name].length);
  for (failure of [undefined, 'open', 'prepare', 'execute', 'close']) {
    assert.deepEqual(capture(refactored, name, args), capture(original, name, args), "'`${name}: ${failure ?? '"'success'}"'`);
    checked++;
  }
}
delete globalThis.__reportOpenDatabase;
console.log(`Passed ${checked} behavior comparisons covering results, SQL, arguments, connection modes, errors and cleanup.`);
